    def _propagate(self):
        # Collect every compute cell reachable from this input.
        affected = {}
        stack = list(self._dependents)
        while stack:
            cell = stack.pop()
            if id(cell) in affected:
                continue
            affected[id(cell)] = cell
            stack.extend(cell._dependents)

